mapper.select:
select * from fnd_interface_lines t1

    1=1

        and t1.header_id = #{headerId}


        and t1.sheet_name = #{sheetName}


        and cast(t1.attributes_5 as char(2000)) = cast(#{attributes_5} as char(2000))


order by line_number

select line_id,header_id,line_number,status,error_message,sheet_name, attributes_1, attributes_2, attributes_3, attributes_4, attributes_5, attributes_6 from fnd_interface_lines
header_id = #{headerId}
and cast(attributes_2 AS char(500)) = cast(#{attributes_2} AS char(500))
and sheet_name = #{sheetName}

select line_id,header_id,line_number,status,error_message,sheet_name, cast(attributes_1 AS char(500)) AS attributes_1,cast(attributes_2 AS char(500)) AS attributes_2,cast(attributes_3 AS char(500)) AS attributes_3,cast(attributes_4 AS char(500)) AS attributes_4, cast(attributes_5 AS char(500)) AS attributes_5,cast(attributes_6 AS char(500)) AS attributes_6 from fnd_interface_lines
cast(attributes_1 AS char(500))!='科目代码'
and header_id = #{headerId}
and cast(attributes_2 AS char(500)) = cast(#{attributes_2} AS char(500))
and sheet_name = #{sheetName}
and cast(attributes_1 AS char(500)) != ' ' order by line_number

select line_id,header_id,line_number,status,error_message,sheet_name, attributes_1, attributes_2, attributes_3, attributes_4, attributes_5, attributes_6 from fnd_interface_lines
header_id = #{headerId}
and sheet_name = #{sheetName}
AND ( cast(attributes_1 AS char(500)) = CAST('项目' AS CHAR(500) ) or cast(attributes_1 AS char(500)) = cast('报告年月' AS CHAR(500)))
order by line_number

select line_id,header_id,line_number,status,error_message,sheet_name, attributes_1, attributes_2, attributes_3, attributes_4, attributes_5, attributes_6 from fnd_interface_lines
header_id = #{headerId}
and sheet_name = #{sheetName}
order by line_number

select line_id,header_id,line_number,status,error_message,sheet_name, attributes_1, (case when attributes_2='-' then '-' when attributes_2 is null then '' else attributes_2 end) attributes_2 , (case when attributes_3='-' then '-' when attributes_2 is null then '' else attributes_2 end)attributes_3, (case when attributes_4='-' then '-' when attributes_2 is null then '' else attributes_2 end)attributes_4, (case when attributes_5='-' then '-' when attributes_2 is null then '' else attributes_2 end)attributes_5, (case when attributes_6='-' then '-' when attributes_2 is null then '' else attributes_2 end) attributes_6 from fnd_interface_lines
header_id = #{headerId}
and sheet_name = #{sheetName}
order by line_number

select line_id,header_id, line_number, status, error_message, sheet_name, attributes_1, attributes_2, attributes_3, attributes_4, attributes_5, attributes_6, attributes_7, attributes_8, attributes_9, attributes_10, attributes_11, attributes_12, attributes_13, attributes_14 from fnd_interface_lines
header_id = #{headerId}
and sheet_name = #{sheetName}
order by line_number
